scanner:
use ferroni::prelude::*;

let mut scanner = Scanner::new(&[
    r"\b(function|const|let|var)\b",
    r#""[^"]*""#,
    r"//.*$",
]).unwrap();

let m = scanner
    .find_next_match(r#"const x = "hello""#, 0, ScannerFindOptions::NONE)
    .unwrap();
assert_eq!(m.index, 0); // "const" matched first

limits:
use std::time::Duration;
use ferroni::prelude::*;

let re = Regex::new(r"(a+)+b").unwrap();
let options = SearchOptions::new()
    .timeout(Duration::from_millis(50));

let hostile = "a".repeat(40);
let result = re.find_with(&hostile, options);
assert!(matches!(result, Err(RegexError::TimeLimitOver)));

